{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T011142Z/cell-2EeEy8/src/diff.js","content":"/**
 * Longest-common-subsequence diffing between a "base" document and one other
 * document ("side"), whole lines compared as exact strings.
 */

/**
 * Finds the matched (baseIndex, sideIndex) pairs of an LCS between `base`
 * and `side`. When several subsequences of the same maximal length exist,
 * picks the one whose matches occur earliest: walking both documents from
 * the start, a match is taken whenever the current lines are equal;
 * otherwise the side whose remaining subsequence stays at least as long is
 * advanced, with base preferred on a tie.
 */
function lcsMatches(base, side) {
  const m = base.length
  const n = side.length
  // dp[i * (n + 1) + j] holds the LCS length of base[i:] and side[j:].
  const width = n + 1
  const dp = new Int32Array((m + 1) * width)
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      const here = i * width + j
      if (base[i] === side[j]) {
        dp[here] = dp[(i + 1) * width + (j + 1)] + 1
      } else {
        const dropBase = dp[(i + 1) * width + j]
        const dropSide = dp[i * width + (j + 1)]
        dp[here] = dropBase > dropSide ? dropBase : dropSide
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < m && j < n) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[(i + 1) * width + j] >= dp[i * width + (j + 1)]) {
      i++
    } else {
      j++
    }
  }
  return matches
}

/**
 * Turns the matched pairs into a list of changes: each change is a run of
 * base lines (possibly empty, for a pure insertion) replaced by a run of
 * side lines (possibly empty, for a pure deletion).
 */
function changesFromMatches(base, side, matches) {
  const changes = []
  let prevB = 0
  let prevS = 0
  for (const [bi, sj] of matches) {
    if (bi > prevB || sj > prevS) {
      changes.push({ baseStart: prevB, baseEnd: bi, sideStart: prevS, sideEnd: sj, lines: side.slice(prevS, sj) })
    }
    prevB = bi + 1
    prevS = sj + 1
  }
  if (prevB < base.length || prevS < side.length) {
    changes.push({ baseStart: prevB, baseEnd: base.length, sideStart: prevS, sideEnd: side.length, lines: side.slice(prevS, side.length) })
  }
  return changes
}

/** Computes the list of changes that turn `base` into `side`. */
export function diff(base, side) {
  const matches = lcsMatches(base, side)
  return changesFromMatches(base, side, matches)
}
"}

