{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T011142Z/cell-2EeEy8/src/regions.js","content":"import { diff } from './diff.js'

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Groups the changes from both sides (sorted by base start, mine before
 * theirs on a tie) into regions: a region runs from the base start of its
 * first change to the base end of the last change absorbed into it, where a
 * change is absorbed whenever it starts at or before the region's current
 * end.
 */
function groupRegions(mineChanges, theirsChanges) {
  const tagged = [
    ...mineChanges.map(c => ({ ...c, side: 'mine' })),
    ...theirsChanges.map(c => ({ ...c, side: 'theirs' })),
  ].sort((a, b) => a.baseStart - b.baseStart)

  const regions = []
  let i = 0
  while (i < tagged.length) {
    const region = { baseStart: tagged[i].baseStart, baseEnd: tagged[i].baseEnd, changes: [tagged[i]] }
    i++
    while (i < tagged.length && tagged[i].baseStart <= region.baseEnd) {
      if (tagged[i].baseEnd > region.baseEnd) region.baseEnd = tagged[i].baseEnd
      region.changes.push(tagged[i])
      i++
    }
    regions.push(region)
  }
  return regions
}

/**
 * The lines one side contributes to a region: its own changes' lines, with
 * the base lines of any part of the region that side left untouched (before,
 * between, or after its own changes) filled in around them.
 */
function sideLines(region, side, baseDoc) {
  const own = region.changes.filter(c => c.side === side)
  const lines = []
  let cursor = region.baseStart
  for (const change of own) {
    lines.push(...baseDoc.slice(cursor, change.baseStart))
    lines.push(...change.lines)
    cursor = change.baseEnd
  }
  lines.push(...baseDoc.slice(cursor, region.baseEnd))
  return lines
}

/**
 * Resolves a region touched by changes into either a clean pick ('mine',
 * 'theirs' or 'both', with the lines it resolves to) or a conflict (with all
 * three of mine's, base's and theirs's lines for the region).
 */
function resolveRegion(region, baseDoc) {
  const touchedSides = new Set(region.changes.map(c => c.side))
  const mine = sideLines(region, 'mine', baseDoc)
  const theirs = sideLines(region, 'theirs', baseDoc)

  if (touchedSides.size === 1) {
    const side = region.changes[0].side
    return { kind: side, lines: side === 'mine' ? mine : theirs }
  }

  const base = baseDoc.slice(region.baseStart, region.baseEnd)
  if (arraysEqual(mine, theirs)) return { kind: 'both', lines: mine }
  if (arraysEqual(mine, base)) return { kind: 'theirs', lines: theirs }
  if (arraysEqual(theirs, base)) return { kind: 'mine', lines: mine }
  return { kind: 'conflict', mine, base, theirs }
}

/**
 * Builds the full ordered list of merge units for the base document: stable
 * runs of unchanged base lines interleaved with resolved (or conflicting)
 * regions.
 */
export function buildUnits(mineDoc, baseDoc, theirsDoc) {
  const mineChanges = diff(baseDoc, mineDoc)
  const theirsChanges = diff(baseDoc, theirsDoc)
  const regions = groupRegions(mineChanges, theirsChanges)

  const units = []
  let cursor = 0
  for (const region of regions) {
    if (region.baseStart > cursor) {
      units.push({ kind: 'stable', lines: baseDoc.slice(cursor, region.baseStart) })
    }
    units.push(resolveRegion(region, baseDoc))
    cursor = region.baseEnd
  }
  if (cursor < baseDoc.length) {
    units.push({ kind: 'stable', lines: baseDoc.slice(cursor, baseDoc.length) })
  }
  return units
}
"}

