export class InputError extends Error {}

/**
 * Splits stdin's raw text into the three documents (mine, base, theirs) it
 * holds, separated by lines that are exactly `%%%`.
 */
export function parseDocuments(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const groups = [[]]
  for (const line of lines) {
    if (line === '%%%') groups.push([])
    else groups[groups.length - 1].push(line)
  }

  if (groups.length !== 3) {
    throw new InputError('error: expected three parts separated by %%%')
  }
  return groups
}
"}

