{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T011142Z/cell-2EeEy8/src/format.js","content":"/**
 * Renders merge units (as produced by `buildUnits`) into the output text for
 * one of the three CLI modes. Returns the text and whether a conflict was
 * written, which decides the process exit code.
 */
export function render(units, mode) {
  const out = []
  let hadConflict = false

  for (const unit of units) {
    if (mode === 'regions') {
      out.push(...renderRegionLine(unit))
      continue
    }

    if (unit.kind === 'conflict') {
      hadConflict = true
      out.push('<<<<<<< mine', ...unit.mine)
      if (mode === 'merge') out.push('||||||| base', ...unit.base)
      out.push('=======', ...unit.theirs, '>>>>>>> theirs')
    } else {
      out.push(...unit.lines)
    }
  }

  return { text: out.length === 0 ? '' : out.join('\n') + '\n', hadConflict }
}

function renderRegionLine(unit) {
  if (unit.kind === 'conflict') {
    return [`conflict mine=${unit.mine.length} base=${unit.base.length} theirs=${unit.theirs.length}`]
  }
  return [`${unit.kind} ${unit.lines.length}`]
}
"}

