/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */
import { readFileSync } from 'node:fs'
import { parseDocuments, InputError } from './parse.js'
import { buildUnits } from './regions.js'
import { render } from './format.js'

const MODES = ['merge', 'merge2', 'regions']

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.includes(mode)) {
    fail('error: usage: cli.js merge|merge2|regions')
  }

  const input = readFileSync(0, 'utf8')
  let mine, base, theirs
  try {
    ;[mine, base, theirs] = parseDocuments(input)
  } catch (err) {
    if (err instanceof InputError) fail(err.message)
    throw err
  }

  const units = buildUnits(mine, base, theirs)
  const { text, hadConflict } = render(units, mode)
  process.stdout.write(text)
  process.exit(hadConflict ? 1 : 0)
}

