const { spawnSync } = require("node:child_process");
function run(argv, mine, base, theirs) {
  const input = [mine, base, theirs].map(part => part.map(l => l + "\n").join("")).join("%%%\n");
  const r = spawnSync(process.execPath, ["src/cli.js", ...argv], { encoding: "utf8", input });
  return { code: r.status, out: r.stdout, err: r.stderr };
}

// No args
console.log("no args:", JSON.stringify(run([], [], [], [])));
// extra args
console.log("extra args:", JSON.stringify(run(["merge","x"], [], [], [])));

// insertion at start both sides identical -> both
console.log("both-insert-start:", JSON.stringify(run(["regions"], ["Q","a"], ["a"], ["Q","a"])));

// deletion both sides -> both, zero lines
console.log("both-delete:", JSON.stringify(run(["regions"], ["a","c"], ["a","b","c"], ["a","c"])));

// multi-change region merged (adjacent changes)
console.log("adjacent:", JSON.stringify(run(["merge"], ["a","X","Y","d"], ["a","b","c","d"], ["a","X","Y","d"])));

// conflicting insert at same base position, different content -> conflict? both insert nothing common
console.log("insert-conflict:", JSON.stringify(run(["merge"], ["a","M","b"], ["a","b"], ["a","T","b"])));

// mine deletes, theirs modifies same run -> mine=base false, theirs=base false -> conflict
console.log("del-vs-mod:", JSON.stringify(run(["merge"], ["a","c"], ["a","b","c"], ["a","Z","c"])));
'
","description":"Manual edge-case checks"}

